import{_ as s,o as i,c as a,ai as r}from"./chunks/framework.Kklb8t0u.js";const u=JSON.parse('{"title":"Logging in Aether","description":"","frontmatter":{},"headers":[],"relativePath":"LOGGING.md","filePath":"LOGGING.md"}'),n={name:"LOGGING.md"};function l(t,e,o,p,d,h){return i(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="logging-in-aether" tabindex="-1">Logging in Aether <a class="header-anchor" href="#logging-in-aether" aria-label="Permalink to &quot;Logging in Aether&quot;">​</a></h1><h2 id="log-levels" tabindex="-1">Log Levels <a class="header-anchor" href="#log-levels" aria-label="Permalink to &quot;Log Levels&quot;">​</a></h2><p>Aether supports multiple log levels for controlling output verbosity:</p><ul><li><strong>ERROR</strong>: Critical errors that cause operations to fail</li><li><strong>WARN</strong>: Warnings about issues that don&#39;t stop execution (e.g., retries)</li><li><strong>INFO</strong>: General informational messages about pipeline progress</li><li><strong>DEBUG</strong>: Detailed debug information for troubleshooting</li></ul><h2 id="enabling-verbose-logging" tabindex="-1">Enabling Verbose Logging <a class="header-anchor" href="#enabling-verbose-logging" aria-label="Permalink to &quot;Enabling Verbose Logging&quot;">​</a></h2><p>Use the <code>--verbose</code> or <code>-v</code> flag to enable DEBUG level logging:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/aether</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pipeline</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --input</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test-data/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aether.yaml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --verbose</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="what-gets-logged-at-each-level" tabindex="-1">What Gets Logged at Each Level <a class="header-anchor" href="#what-gets-logged-at-each-level" aria-label="Permalink to &quot;What Gets Logged at Each Level&quot;">​</a></h2><h3 id="debug-level-verbose" tabindex="-1">DEBUG Level (--verbose) <a class="header-anchor" href="#debug-level-verbose" aria-label="Permalink to &quot;DEBUG Level (--verbose)&quot;">​</a></h3><p>When you use <code>--verbose</code>, you&#39;ll see:</p><p><strong>DIMP Processing:</strong></p><ul><li>Each resource being sent to DIMP (resourceType, ID, URL)</li><li>Request body size</li><li>DIMP service responses (status code, resource info)</li><li>Resource ID transformations (original → pseudonymized)</li><li>Each FHIR resource being processed (file, line number, resourceType, ID)</li></ul><p><strong>Import Processing:</strong></p><ul><li>Individual file imports with details (filename, size, resource count)</li></ul><p><strong>HTTP Requests:</strong></p><ul><li>Service call details (endpoint, method)</li><li>Service response details (status, duration)</li></ul><h3 id="info-level-default" tabindex="-1">INFO Level (default) <a class="header-anchor" href="#info-level-default" aria-label="Permalink to &quot;INFO Level (default)&quot;">​</a></h3><p>Without <code>--verbose</code>, you&#39;ll see:</p><ul><li>Job creation and completion</li><li>Step start/completion with file counts and duration</li><li>DIMP file processing progress (file X of Y)</li><li>Successfully processed files with resource counts</li><li>Major pipeline events</li></ul><h3 id="warn-level" tabindex="-1">WARN Level <a class="header-anchor" href="#warn-level" aria-label="Permalink to &quot;WARN Level&quot;">​</a></h3><p>Always shown:</p><ul><li>Service errors (HTTP 4xx, 5xx)</li><li>Retry attempts with attempt number and error</li><li>Service connectivity issues</li></ul><h3 id="error-level" tabindex="-1">ERROR Level <a class="header-anchor" href="#error-level" aria-label="Permalink to &quot;ERROR Level&quot;">​</a></h3><p>Always shown:</p><ul><li>Critical failures that stop the pipeline</li><li>Step failures with error details</li><li>HTTP request failures</li><li>Failed to parse/pseudonymize specific resources</li><li><strong>DIMP errors with full error response body</strong></li></ul><h2 id="dimp-specific-logging" tabindex="-1">DIMP-Specific Logging <a class="header-anchor" href="#dimp-specific-logging" aria-label="Permalink to &quot;DIMP-Specific Logging&quot;">​</a></h2><p>With <code>--verbose</code>, for each resource the DIMP step processes, you&#39;ll see:</p><ol><li><p><strong>Before pseudonymization:</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[DEBUG] Sending resource to DIMP | [resourceType Patient id abc-123 url http://localhost:33048/fhir/$de-identify]</span></span>
<span class="line"><span>[DEBUG] Request body size | [bytes 1234]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div></li><li><p><strong>On success:</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[DEBUG] DIMP service responded successfully | [status_code 200 resourceType Patient id abc-123]</span></span>
<span class="line"><span>[DEBUG] Resource ID pseudonymized | [resourceType Patient original_id abc-123 new_id xyz-789-hashed]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div></li><li><p><strong>On error:</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ERROR] DIMP service returned error | [status_code 500 status 500 Internal Server Error resourceType Patient id abc-123 error_body {...full error response...} retryable true]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li></ol><h2 id="example-debugging-dimp-500-errors" tabindex="-1">Example: Debugging DIMP 500 Errors <a class="header-anchor" href="#example-debugging-dimp-500-errors" aria-label="Permalink to &quot;Example: Debugging DIMP 500 Errors&quot;">​</a></h2><p>Run with verbose logging to see the full error details:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/aether</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pipeline</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --input</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test-data/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .github/test/aether.yaml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --verbose</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Look for these log entries:</p><ul><li><code>[ERROR] DIMP service returned error</code> - Shows the full error response from DIMP</li><li><code>[ERROR] Failed to pseudonymize FHIR resource</code> - Shows which specific resource failed</li><li><code>[INFO] Processing FHIR file through DIMP</code> - Shows which file is being processed</li><li><code>[WARN] Retry attempt X/5</code> - Shows retry attempts for transient errors</li></ul><h2 id="example-output-verbose-mode" tabindex="-1">Example Output (verbose mode) <a class="header-anchor" href="#example-output-verbose-mode" aria-label="Permalink to &quot;Example Output (verbose mode)&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2025/10/09 13:40:41 [INFO] Processing FHIR file through DIMP | [file_number 1 total_files 13 filename test.ndjson job_id abc-123]</span></span>
<span class="line"><span>2025/10/09 13:40:41 [DEBUG] Processing FHIR resource | [file test.ndjson line_number 1 resourceType Patient id patient-001]</span></span>
<span class="line"><span>2025/10/09 13:40:41 [DEBUG] Sending resource to DIMP | [resourceType Patient id patient-001 url http://localhost:33048/fhir/$de-identify]</span></span>
<span class="line"><span>2025/10/09 13:40:41 [DEBUG] Request body size | [bytes 456]</span></span>
<span class="line"><span>2025/10/09 13:40:41 [ERROR] DIMP service returned error | [status_code 500 status 500 Internal Server Error resourceType Patient id patient-001 error_body {&quot;error&quot;:&quot;Invalid resource format&quot;} retryable true]</span></span>
<span class="line"><span>2025/10/09 13:40:41 [WARN] Retry attempt 1/5 for: http://localhost:33048/fhir/$de-identify | [error HTTP 500: 500 Internal Server Error]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h2 id="checking-docker-logs-for-dimp-service" tabindex="-1">Checking Docker Logs for DIMP Service <a class="header-anchor" href="#checking-docker-logs-for-dimp-service" aria-label="Permalink to &quot;Checking Docker Logs for DIMP Service&quot;">​</a></h2><p>If DIMP is returning errors, also check the service logs:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .github/test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fhir-pseudonymizer</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tail</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 50</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>This will show what&#39;s happening on the DIMP service side.</p><h2 id="tips-for-troubleshooting" tabindex="-1">Tips for Troubleshooting <a class="header-anchor" href="#tips-for-troubleshooting" aria-label="Permalink to &quot;Tips for Troubleshooting&quot;">​</a></h2><ol><li><strong>Always use <code>--verbose</code> when debugging</strong> - It shows the actual error responses from services</li><li><strong>Check both aether logs and Docker logs</strong> - The issue might be in the service itself</li><li><strong>Look for the <code>error_body</code> field</strong> - This contains the full error response from DIMP</li><li><strong>Note the resource that fails</strong> - The logs show exactly which resourceType and ID caused the error</li><li><strong>Check retry behavior</strong> - <code>retryable true/false</code> tells you if the error will be retried</li></ol><h2 id="log-format" tabindex="-1">Log Format <a class="header-anchor" href="#log-format" aria-label="Permalink to &quot;Log Format&quot;">​</a></h2><p>All logs follow this format:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TIMESTAMP [LEVEL] Message | [key1 value1 key2 value2 ...]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Example:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2025/10/09 13:40:41 [ERROR] DIMP service returned error | [status_code 500 resourceType Patient error_body {...}]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div>`,46)])])}const g=s(n,[["render",l]]);export{u as __pageData,g as default};
